package mz.gov.mogovolas.expedientes.service; import mz.gov.mogovolas.expedientes.entity.*; import mz.gov.mogovolas.expedientes.repository.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.nio.file.*; import java.time.*; import java.util.*;
@Service public class AnexoService {final AnexoRepository repo;final ExpedienteRepository exps;final UtilizadorRepository users;final Path root; public AnexoService(AnexoRepository r,ExpedienteRepository e,UtilizadorRepository u,@Value("${file.storage-path:./storage}")String p){repo=r;exps=e;users=u;root=Paths.get(p).toAbsolutePath().normalize();try{Files.createDirectories(root);}catch(IOException x){throw new IllegalStateException(x);}} public Anexo guardar(Long id,MultipartFile f,String user)throws IOException{if(f.isEmpty()||f.getSize()>10_000_000)throw new IllegalArgumentException("Ficheiro vazio ou superior a 10 MB");String original=Optional.ofNullable(f.getOriginalFilename()).orElse("ficheiro");String stored=UUID.randomUUID()+"-"+Path.of(original).getFileName();Files.copy(f.getInputStream(),root.resolve(stored),StandardCopyOption.REPLACE_EXISTING);Anexo a=new Anexo();a.setExpediente(exps.findById(id).orElseThrow());a.setNomeOriginal(original);a.setNomeArmazenado(stored);a.setContentType(f.getContentType());a.setTamanho(f.getSize());a.setEnviadoPor(users.findByUsername(user).orElseThrow());a.setDataUpload(LocalDateTime.now());return repo.save(a);} public ResourceData ler(Long id)throws IOException{Anexo a=repo.findById(id).orElseThrow();return new ResourceData(a,Files.readAllBytes(root.resolve(a.getNomeArmazenado())));} public record ResourceData(Anexo anexo,byte[] bytes){} }
